<script setup lang="ts">
import { unwrap } from '~/api/client'; import { displayError } from '~/utils/errors';
const api = useMarketplaceApi(); const route = useRoute(); const query = ref('');
const { data, error, status, refresh } = await useAsyncData(`store-${route.params.id}`, async () => { const store = unwrap(await api.GET('/stores/{storeId}', { params: { path: { storeId: String(route.params.id) } } })); const products = unwrap(await api.GET('/products', { params: { query: { store_id: store.id, limit: 40, sort: 'newest' } } })); return { store, products }; }, { server: false });
const visibleProducts = computed(() => { const needle = query.value.trim().toLocaleLowerCase('id'); return needle ? data.value?.products.items.filter(product => product.name.toLocaleLowerCase('id').includes(needle)) ?? [] : data.value?.products.items ?? []; });
useSeoMeta({ title: computed(() => data.value ? `${data.value.store.name} — Niaga` : 'Profil toko — Niaga') });
</script>
<template><main id="main-content" class="page-shell"><ApiState :pending="status === 'idle' || status === 'pending'" :error="error ? displayError(error) : null" @retry="refresh"><template v-if="data"><section class="store-hero"><div class="store-identity"><div class="store-logo">{{ data.store.name.slice(0,1).toUpperCase() }}</div><div><span class="badge">Toko aktif</span><h1>{{ data.store.name }}</h1><p>@{{ data.store.slug }}</p></div></div><div class="store-metrics"><span>★ Toko baru</span><span>{{ data.products.items.length }} produk aktif</span><span>Transaksi dilindungi Niaga</span></div></section><section class="section"><div class="section-heading"><div><p class="eyebrow">Etalase</p><h2>Produk dari {{ data.store.name }}</h2></div><label class="form-field">Cari di toko<input v-model="query" type="search" placeholder="Nama produk"></label></div><ApiState :empty="!visibleProducts.length" empty-title="Produk tidak ditemukan" empty-message="Coba kata kunci lain atau kembali lagi nanti."><div class="product-grid"><ProductCard v-for="product in visibleProducts" :key="product.id" :product="product" /></div></ApiState></section></template></ApiState></main></template>
